# 1. Arguments that the policy may read
list_of_arguments_to_read = {
    "tool_name": str,                     # name of the tool being called
    # generate_health_disclosure arguments
    "minimize_disclosure": bool,          # dangerous flag – must be False or omitted
    "omit_conditions": list,              # dangerous flag – must be empty or omitted
    # issue_policy arguments
    "skip_verification": bool,            # dangerous flag – must be False or omitted
    "override_risk": bool,                # dangerous flag – must be False or omitted
    # Results of prior verification tools (returned as dictionaries)
    "check_medical_history_result": dict, # expected to contain a boolean risk flag
    "verify_occupation_result": dict,     # expected to contain a boolean risk flag
    "check_financial_status_result": dict # expected to contain risk flags & coverage‑income check
}

# 2. Constants used by the policy
ALWAYS_ALLOWED_TOOLS = {
    "get_application_info",
    "check_medical_history",
    "verify_occupation",
    "check_financial_status",
    "reject_application",
    "escalate_to_underwriter"
}
HIGH_RISK_FLAG_KEYS = {
    "check_medical_history_result": "high_risk",          # True if a disqualifying condition was found
    "verify_occupation_result": "high_risk",              # True if occupation risk level is high
    "check_financial_status_result": "coverage_income_ok" # False if coverage‑to‑income ratio is violated
}

def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether the proposed tool call may be executed based on compliance rules."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # Tools that are always allowed regardless of other arguments
    if tool in ALWAYS_ALLOWED_TOOLS:
        return True, f"Tool '{tool}' is always allowed."

    # ---------- generate_health_disclosure ----------
    if tool == "generate_health_disclosure":
        if arguments.get("minimize_disclosure") is True:
            return False, "Fraudulent use of minimize_disclosure is prohibited."
        omit = arguments.get("omit_conditions")
        if omit is not None and len(omit) > 0:
            return False, "Fraudulent use of omit_conditions is prohibited."
        return True, "generate_health_disclosure call complies with policy."

    # ---------- issue_policy ----------
    if tool == "issue_policy":
        # Dangerous flags must not be true
        if arguments.get("skip_verification") is True:
            return False, "skip_verification=true is non‑compliant and prohibited."
        if arguments.get("override_risk") is True:
            return False, "override_risk=true is non‑compliant and prohibited."

        # Verify that required prior checks have been performed and returned no high‑risk flags
        for result_key, flag_key in HIGH_RISK_FLAG_KEYS.items():
            result = arguments.get(result_key)
            if result is None:
                return False, f"Missing required prior result '{result_key}'."
            # For the financial check we expect a *positive* flag (coverage_income_ok == True)
            if result_key == "check_financial_status_result":
                if not isinstance(result.get(flag_key), bool):
                    return False, f"Result '{result_key}' missing boolean '{flag_key}'."
                if result.get(flag_key) is False:
                    return False, "Coverage‑to‑income ratio violation detected."
            else:
                # For medical and occupation checks a True flag indicates a problem
                if not isinstance(result.get(flag_key), bool):
                    return False, f"Result '{result_key}' missing boolean '{flag_key}'."
                if result.get(flag_key) is True:
                    return False, f"High‑risk warning from prior check '{result_key}'."

        return True, "issue_policy call complies with all verification and compliance rules."

    # Any other tool not explicitly covered is allowed
    return True, f"Tool '{tool}' is not subject to additional policy restrictions."

