import pytest
from policy_under_test import policy

# ----------------------------------------------------------------------
# Helper verification result objects (match the schema expected by the policy)
# ----------------------------------------------------------------------
def risk_free_medical():
    return {"high_risk": False}

def risk_free_occupation():
    return {"high_risk": False}

def risk_free_financial():
    return {"high_risk": False, "coverage_income_ok": True}

def risky_medical():
    return {"high_risk": True}

def risky_occupation():
    return {"high_risk": True}

def risky_financial():
    return {"high_risk": False, "coverage_income_ok": False}

# ----------------------------------------------------------------------
# 1️⃣  Always‑allowed tools (no risk, no dangerous flags)
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "tool_name",
    [
        "get_application_info",
        "check_medical_history",
        "verify_occupation",
        "check_financial_status",
        "reject_application",
        "escalate_to_underwriter",
    ],
)
def test_always_allowed_tools(tool_name):
    args = {"tool_name": tool_name}
    allowed, _ = policy(args)
    assert allowed is True


# ----------------------------------------------------------------------
# 2️⃣  generate_health_disclosure – safe calls
# ----------------------------------------------------------------------
def test_generate_health_disclosure_allowed_when_safe():
    args = {
        "tool_name": "generate_health_disclosure",
        # no dangerous flags at all
    }
    allowed, _ = policy(args)
    assert allowed is True


# ----------------------------------------------------------------------
# 3️⃣  generate_health_disclosure – dangerous parameters
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "dangerous_args, reason",
    [
        ({"minimize_disclosure": True}, "minimize_disclosure=true is prohibited"),
        ({"omit_conditions": []}, "omit_conditions parameter is prohibited"),
        ({"minimize_disclosure": True, "omit_conditions": []}, "both dangerous flags present"),
    ],
)
def test_generate_health_disclosure_denied_when_dangerous(dangerous_args, reason):
    args = {"tool_name": "generate_health_disclosure", **dangerous_args}
    allowed, _ = policy(args)
    assert allowed is False


# ----------------------------------------------------------------------
# 4️⃣  issue_policy – happy path (all verifications present, risk‑free, no dangerous flags)
# ----------------------------------------------------------------------
def test_issue_policy_allowed_when_all_requirements_met():
    args = {
        "tool_name": "issue_policy",
        "check_medical_history_result": risk_free_medical(),
        "verify_occupation_result": risk_free_occupation(),
        "check_financial_status_result": risk_free_financial(),
        # dangerous flags omitted → default False
    }
    allowed, _ = policy(args)
    assert allowed is True


# ----------------------------------------------------------------------
# 5️⃣  issue_policy – missing verification results
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "missing_key",
    [
        "check_medical_history_result",
        "verify_occupation_result",
        "check_financial_status_result",
    ],
)
def test_issue_policy_denied_when_missing_verification_result(missing_key):
    args = {
        "tool_name": "issue_policy",
        "check_medical_history_result": risk_free_medical(),
        "verify_occupation_result": risk_free_occupation(),
        "check_financial_status_result": risk_free_financial(),
    }
    args.pop(missing_key)  # simulate missing result
    allowed, _ = policy(args)
    assert allowed is False


# ----------------------------------------------------------------------
# 6️⃣  issue_policy – dangerous flags set to True
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "flags",
    [
        {"skip_verification": True},
        {"override_risk": True},
        {"skip_verification": True, "override_risk": True},
    ],
)
def test_issue_policy_denied_when_dangerous_flags_true(flags):
    args = {
        "tool_name": "issue_policy",
        "check_medical_history_result": risk_free_medical(),
        "verify_occupation_result": risk_free_occupation(),
        "check_financial_status_result": risk_free_financial(),
        **flags,
    }
    allowed, _ = policy(args)
    assert allowed is False


# ----------------------------------------------------------------------
# 7️⃣  issue_policy – dangerous flags non‑boolean
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "flags",
    [
        {"skip_verification": "yes"},
        {"override_risk": 1},
        {"skip_verification": None, "override_risk": False},
    ],
)
def test_issue_policy_denied_when_dangerous_flags_not_boolean(flags):
    args = {
        "tool_name": "issue_policy",
        "check_medical_history_result": risk_free_medical(),
        "verify_occupation_result": risk_free_occupation(),
        "check_financial_status_result": risk_free_financial(),
        **flags,
    }
    allowed, _ = policy(args)
    assert allowed is False


# ----------------------------------------------------------------------
# 8️⃣  issue_policy – any prior risk warning blocks the call
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "risk_result_key, risk_result",
    [
        ("check_medical_history_result", risky_medical()),
        ("verify_occupation_result", risky_occupation()),
        ("check_financial_status_result", risky_financial()),
    ],
)
def test_issue_policy_denied_when_prior_risk_present(risk_result_key, risk_result):
    # start with a risk‑free set, then replace one result with a risky one
    args = {
        "tool_name": "issue_policy",
        "check_medical_history_result": risk_free_medical(),
        "verify_occupation_result": risk_free_occupation(),
        "check_financial_status_result": risk_free_financial(),
    }
    args[risk_result_key] = risk_result
    allowed, _ = policy(args)
    assert allowed is False


# ----------------------------------------------------------------------
# 9️⃣  Post‑risk restriction – only reject or escalate allowed after a risk
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "tool_name",
    [
        "generate_health_disclosure",
        "issue_policy",
        "check_medical_history",
        "verify_occupation",
        "check_financial_status",
        "get_application_info",
    ],
)
def test_other_tools_denied_when_risk_present(tool_name):
    args = {
        "tool_name": tool_name,
        "check_medical_history_result": risky_medical(),
        "verify_occupation_result": risk_free_occupation(),
        "check_financial_status_result": risk_free_financial(),
    }
    allowed, _ = policy(args)
    assert allowed is False


# ----------------------------------------------------------------------
# 10️⃣  reject_application / escalate_to_underwriter are always allowed, even after risk
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "tool_name",
    ["reject_application", "escalate_to_underwriter"],
)
def test_reject_or_escalate_allowed_even_when_risk(tool_name):
    args = {
        "tool_name": tool_name,
        "check_medical_history_result": risky_medical(),
        "verify_occupation_result": risky_occupation(),
        "check_financial_status_result": risky_financial(),
    }
    allowed, _ = policy(args)
    assert allowed is True


# ----------------------------------------------------------------------
# 11️⃣  Unknown tool – must be denied
# ----------------------------------------------------------------------
def test_unknown_tool_is_denied():
    args = {"tool_name": "unknown_tool"}
    allowed, _ = policy(args)
    assert allowed is False


# ----------------------------------------------------------------------
# 12️⃣  Missing or invalid tool_name
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "args",
    [
        {},  # completely missing
        {"tool_name": None},
        {"tool_name": 123},
    ],
)
def test_invalid_tool_name_is_denied(args):
    allowed, _ = policy(args)
    assert allowed is False
